#include <stdio.h>
#include <string.h>
#include <ctype.h>

#define MAX_LEN 1024

int main(int argc, char *argv[])
{
    if (argc < 3) {
        puts("USAGE");
        return 0;
    }
    const char *s1 = argv[1];
    const char *s2 = argv[2];
    if (strlen(s1) >= MAX_LEN || strlen(s2) >= MAX_LEN) {
        puts("TOO_LONG");
        return 0;
    }
    int cnt1[256] = {0};
    int cnt2[256] = {0};
    for (const unsigned char *p = (const unsigned char *)s1; *p; ++p) {
        if (*p == ' ') continue;
        if (isalpha(*p)) cnt1[tolower(*p)]++;
        else cnt1[*p]++;
    }
    for (const unsigned char *p = (const unsigned char *)s2; *p; ++p) {
        if (*p == ' ') continue;
        if (isalpha(*p)) cnt2[tolower(*p)]++;
        else cnt2[*p]++;
    }
    int ok = 1;
    for (int i = 0; i < 256; ++i) if (cnt1[i] != cnt2[i]) { ok = 0; break; }
    puts(ok ? "ANAGRAM" : "NOT_ANAGRAM");
    return 0;
}
